impl JsonSchema for WidgetValue {}

/// Begin a container scope with an explicit id.
///
/// Every widget recorded while the guard lives takes `id` as its parent. Use
/// this when the container widget itself is recorded elsewhere, such as a
/// window whose response is only available after its contents have rendered.
/// Use [`container`] when the scope and the container widget can be recorded
/// together, and [`publish_rect_container`] for a painter-drawn parent.
pub fn begin_container(ui: &Ui, id: impl Into<String>) -> ContainerGuard;

/// Capture layout metadata for an already-rendered custom widget response.
pub fn capture_layout(ui: &Ui, response: &Response) -> WidgetLayout;

/// Capture layout metadata plus the exact galley that a text widget painted.
pub fn capture_layout_with_galley(ui: &Ui, response: &Response, galley: &Galley) -> WidgetLayout;

/// Run a closure within a container scope with an explicit id.
///
/// The container is registered as a widget so it is discoverable via `parent()`
/// and `children()`.
pub fn container<R>(
    ui: &mut Ui,
    id: impl Into<String>,
    add_contents: impl FnOnce(&mut Ui) -> R,
) -> R;

/// Wrap one viewport frame and register `container_id` as its root container.
///
/// Call this once for each rendered viewport pass, and render all instrumented
/// widgets for that pass inside `add_contents`. Consume pending fixture state
/// inside the closure too, so its frame epoch covers the state being rendered.
/// If the viewport has a semantic
/// name, call `name_viewport` from inside `add_contents` so the active frame is
/// already installed.
pub fn frame_scope<R>(
    devmcp: &DevMcp,
    ui: &mut Ui,
    container_id: impl Into<String>,
    add_contents: impl FnOnce(&mut Ui) -> R,
) -> R;

/// Register a semantic name for the viewport currently rendering in `ctx`.
///
/// Call this every frame from inside that viewport's instrumented pass, after
/// `FrameGuard` or `frame_scope` has made the frame active. Calls outside an
/// active instrumentation frame are ignored, which keeps production rendering
/// code usable when DevMCP is disabled.
pub fn name_viewport(ctx: &Context, name: impl Into<String>);

/// Publish a painter-drawn rect and open a container scope with the same id.
///
/// This is the documented form for a painter-drawn hierarchy. Every rect that
/// [`publish_rect_meta`] publishes while the returned guard lives becomes a
/// child of `id`, so `check_layout` reads containment as intentional structure
/// instead of one overlap per child, and the children inherit the parent's clip
/// rect. The guard pops the scope on drop.
///
/// Set [`WidgetMeta::visible`] on the canvas and on each child. A published
/// rect has no `egui::Response` to derive visibility from, and the field
/// defaults to `false`.
///
/// ```rust,ignore
/// let _board = publish_rect_container(ui, "board.canvas", board_rect, canvas_meta());
/// for (name, rect) in squares {
///     publish_rect_meta(ui, format!("board.square.{name}"), rect, square_meta());
/// }
/// ```
pub fn publish_rect_container(
    ui: &Ui,
    id: impl Into<String>,
    rect: egui::Rect,
    meta: WidgetMeta,
) -> ContainerGuard;

/// Publish metadata for a painter-drawn rect that has no `egui::Response`.
///
/// The rect is interpreted in the current UI layer and transformed to global
/// coordinates. A published rect has no `egui::Response`, so it is unfocused,
/// it is enabled unless [`WidgetMeta::enabled`] says otherwise, and it is
/// invisible to automation unless [`WidgetMeta::visible`] is set. Use
/// [`publish_rect_container`] when the rect is a parent for further rects.
pub fn publish_rect_meta(ui: &Ui, id: impl Into<String>, rect: egui::Rect, meta: WidgetMeta);

/// Consume a queued widget value override for a custom instrumented widget.
///
/// Call this every frame that the custom widget is instrumented. The runtime
/// uses that call to distinguish wired custom widgets from widgets that publish
/// a settable value but never consume queued overrides.
pub fn take_widget_value_override(ui: &Ui, id: &str) -> Option<WidgetValue>;

/// Record an already-created widget response with explicit metadata.
///
/// Use this when you hold an `egui::Response` from a custom widget and cannot
/// wrap it with [`track_widget`] or [`track_widget_with_meta`]. Prefer the
/// `DevUiExt` helpers for standard widgets.
///
/// The `track_*` functions record something that has an `egui::Response`, so
/// they can read its enabled, focused, and interaction state. The
/// `publish_rect_*` functions publish painter-drawn geometry, which has none of
/// that, so [`WidgetMeta`] must supply it.
pub fn track_response(id: impl Into<String>, response: &Response, meta: WidgetMeta);

/// Draw a custom widget and record its geometry under an explicit id.
///
/// Prefer `DevUiExt` for standard widgets. Use this when geometry is all the
/// automation needs, and [`track_widget_with_meta`] when it needs a role, a
/// label, or a value.
pub fn track_widget(
    ui: &mut Ui,
    id: impl Into<String>,
    add: impl FnOnce(&mut Ui) -> Response,
) -> Response;

/// Draw a custom widget and record it with explicit role metadata.
///
/// Use this when automation needs the role, label, or value of a custom widget.
/// Use [`track_response`] when the response already exists.
pub fn track_widget_with_meta(
    ui: &mut Ui,
    id: impl Into<String>,
    role: WidgetRoleMeta,
    label: Option<String>,
    value: Option<WidgetValue>,
    add: impl FnOnce(&mut Ui) -> Response,
) -> Response;

